<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';const form=useForm({email:'',password:'',remember:false});</script><template><Head title="Administrator Login"/><main class="flex min-h-screen items-center justify-center bg-slate-950 p-5"><form @submit.prevent="form.post('/admin/login')" class="w-full max-w-md rounded-2xl bg-white p-8 shadow-2xl"><h1 class="text-2xl font-extrabold">MyPro administrator</h1><p class="mt-2 text-sm text-slate-500">Authorized users only. Public registration is disabled.</p><label class="label mt-7">Email<input v-model="form.email" type="email" class="field mt-2" required></label><p class="text-sm text-red-600">{{form.errors.email}}</p><label class="label mt-5">Password<input v-model="form.password" type="password" class="field mt-2" required></label><label class="mt-4 flex gap-2 text-sm"><input v-model="form.remember" type="checkbox">Remember me</label><button class="btn-primary mt-7 w-full" :disabled="form.processing">Sign in</button></form></main></template>
